def solution(results, golden, k):
    # Same maths with list scans instead of sets: O(k * |relevant|) per query.
    if len(golden) == 0:
        return [0.0, 0.0]
    recalls = []
    rrs = []
    for query in golden:
        relevant = golden[query]
        ranked = results[query] if query in results else []
        hits = 0
        for i in range(min(k, len(ranked))):
            if ranked[i] in relevant:
                hits += 1
        recalls.append(hits / len(relevant))
        rr = 0
        i = 0
        while i < len(ranked):
            if ranked[i] in relevant:
                rr = 1 / (i + 1)
                break
            i += 1
        rrs.append(rr)
    return [round(sum(recalls) / len(recalls), 3), round(sum(rrs) / len(rrs), 3)]
